use std::{fs,path::Path,collections::BTreeSet};use serde_json::{json,Value};use sha2::{Digest,Sha256};fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/representative-sdk175");let read=|p:&str|->Value{serde_json::from_slice(&fs::read(r.join(p)).unwrap()).unwrap()};assert!(!r.join("proof-sha256-after.json").exists());assert_eq!(read("runs/result.json")["status"],"complete");let a=read("analysis.json");assert_eq!(a["new_independent_exports"],438);assert_eq!(a["independent_proof_count"],21697);let mut seen:BTreeSet<String>=serde_json::from_value(read("prior-proof-sha256.json")).unwrap();assert_eq!(seen.len(),21259);let inv=read("proof-inventory.json");assert_eq!(inv.as_object().unwrap().len(),876);let mut added=0;for(p,h)in inv.as_object().unwrap(){let bytes=fs::read(p).unwrap();assert_eq!(format!("{:x}",Sha256::digest(&bytes)),h.as_str().unwrap());if p.ends_with(".proof"){assert_eq!(bytes.len(),164);assert!(seen.insert(h.as_str().unwrap().into()));added+=1;}}assert_eq!(added,438);assert_eq!(seen.len(),21697);fs::write(r.join("proof-sha256-after.json"),serde_json::to_vec_pretty(&seen).unwrap()).unwrap();fs::write(r.join("ledger-repair.json"),serde_json::to_vec_pretty(&json!({"prior":21259,"already_Gnark_verified_new":438,"persisted_total":21697,"new_verifier_runs":0,"all_876_inventory_bytes_checked":true,"runtime_tests_captures_gates_unchanged":true})).unwrap()).unwrap();println!("Persisted21697verifiedproofidentities;438alreadyverifiednew;no newverifier/capture/test");}
